const config = {
  "previewFeatures": [],
  "clientVersion": "7.9.0",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "postgresql",
  "inlineSchema": "// ===================================================================\n// BUTWAL SNAKE RESCUE PLATFORM - PRISMA SCHEMA\n// ===================================================================\n// Production-grade PostgreSQL database schema for enterprise snake\n// rescue management, volunteer coordination, AI identification,\n// CMS, and donation system.\n//\n// Reference: https://www.butwalsnake.com/\n// ===================================================================\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  output        = \"../src/prisma/generated\"\n  binaryTargets = [\"native\", \"linux-musl-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ===================================================================\n// USER MANAGEMENT & AUTHENTICATION\n// ===================================================================\n\nmodel User {\n  id       String     @id @default(uuid())\n  email    String     @unique\n  password String? // Null for OAuth users\n  name     String\n  phone    String?\n  role     UserRole   @default(CITIZEN)\n  status   UserStatus @default(ACTIVE)\n  avatar   String?\n\n  // OAuth Integration\n  googleId    String? @unique\n  googleEmail String?\n\n  // Email Verification\n  emailVerified Boolean   @default(false)\n  verifiedAt    DateTime?\n\n  // Security\n  lastLoginAt         DateTime?\n  lastLoginIp         String?\n  passwordResetToken  String?\n  passwordResetExpiry DateTime?\n\n  // Preferences\n  language                String @default(\"en\")\n  timezone                String @default(\"Asia/Kathmandu\")\n  notificationPreferences Json? // Notification preferences\n\n  // Metadata\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime? // Soft delete\n\n  // Relations\n  rescueRequests    RescueRequest[]\n  volunteerProfile  Volunteer?\n  blogPosts         BlogPost[]\n  galleryImages     GalleryImage[]\n  donations         Donation[]\n  aiIdentifications AIIdentification[]\n  notifications     Notification[]\n  activityLogs      ActivityLog[]\n  rescueTimelines   RescueTimeline[]\n  trainings         Training[]\n\n  // Better Auth Relations\n  sessions Session[]\n  accounts Account[]\n\n  // RBAC Relations\n  userRoles UserRoleAssignment[]\n\n  @@index([email])\n  @@index([role])\n  @@index([status])\n  @@index([googleId])\n  @@map(\"users\")\n}\n\nenum UserRole {\n  CITIZEN\n  VOLUNTEER\n  VERIFIED_RESCUER\n  DISTRICT_COORDINATOR\n  ADMIN\n  SUPER_ADMIN\n}\n\nenum UserStatus {\n  ACTIVE\n  INACTIVE\n  SUSPENDED\n  PENDING_VERIFICATION\n  BANNED\n}\n\n// ===================================================================\n// BETTER AUTH TABLES (Authentication)\n// ===================================================================\n\nmodel Session {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token     String   @unique\n  expiresAt DateTime\n  ipAddress String?\n  userAgent String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n  @@index([token])\n  @@map(\"sessions\")\n}\n\nmodel Account {\n  id                String    @id @default(uuid())\n  userId            String\n  user              User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  provider          String // \"google\", \"github\", etc.\n  providerAccountId String\n  accessToken       String?   @db.Text\n  refreshToken      String?   @db.Text\n  expiresAt         DateTime?\n  tokenType         String?\n  scope             String?\n  idToken           String?   @db.Text\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  @@unique([provider, providerAccountId])\n  @@index([userId])\n  @@map(\"accounts\")\n}\n\nmodel Verification {\n  id         String   @id @default(uuid())\n  identifier String // email or phone\n  token      String   @unique\n  type       String // \"email\", \"password-reset\"\n  expiresAt  DateTime\n  createdAt  DateTime @default(now())\n\n  @@index([token])\n  @@index([identifier])\n  @@map(\"verifications\")\n}\n\n// ===================================================================\n// RBAC TABLES (Authorization)\n// ===================================================================\n\nmodel Role {\n  id          String   @id @default(uuid())\n  name        String   @unique // \"ADMIN\", \"VOLUNTEER\", etc.\n  description String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  permissions RolePermission[]\n  userRoles   UserRoleAssignment[]\n\n  @@map(\"roles\")\n}\n\nmodel Permission {\n  id          String   @id @default(uuid())\n  name        String   @unique // \"MANAGE_USERS\", \"ASSIGN_RESCUES\", etc.\n  description String?\n  resource    String // \"users\", \"rescues\", \"volunteers\"\n  action      String // \"create\", \"read\", \"update\", \"delete\"\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  roles RolePermission[]\n\n  @@unique([resource, action])\n  @@map(\"permissions\")\n}\n\nmodel RolePermission {\n  roleId       String\n  role         Role       @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  permissionId String\n  permission   Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  @@id([roleId, permissionId])\n  @@map(\"role_permissions\")\n}\n\nmodel UserRoleAssignment {\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  roleId    String\n  role      Role     @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  grantedAt DateTime @default(now())\n  grantedBy String?\n\n  @@id([userId, roleId])\n  @@map(\"user_role_assignments\")\n}\n\n// ===================================================================\n// RESCUE MANAGEMENT\n// ===================================================================\n\nmodel RescueRequest {\n  id String @id @default(uuid())\n\n  // Reporter Information\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n  name   String\n  phone  String\n  email  String?\n\n  // Location Details\n  municipality     String\n  ward             Int?\n  address          String\n  landmark         String?\n  lat              Float?\n  lng              Float?\n  locationAccuracy Float? // GPS accuracy in meters\n\n  // Snake Information\n  snakeDescription String?\n  snakeSize        String? // \"Small (<1ft)\", \"Medium (1-3ft)\", \"Large (>3ft)\"\n  snakeColor       String?\n  snakeImageUrl    String?\n  snakeImages      String[] // Multiple images\n\n  // Species Identification\n  speciesId          String?\n  species            SnakeSpecies?     @relation(fields: [speciesId], references: [id], onDelete: SetNull)\n  aiIdentificationId String?           @unique\n  aiIdentification   AIIdentification? @relation(fields: [aiIdentificationId], references: [id])\n\n  // Rescue Status\n  status        RescueStatus   @default(PENDING)\n  priority      RescuePriority @default(MEDIUM)\n  stillPresent  Boolean        @default(true)\n  notes         String?        @db.Text\n  internalNotes String?        @db.Text // Admin-only notes\n\n  // Assignment\n  assignedTo        String?\n  assignedVolunteer Volunteer? @relation(fields: [assignedTo], references: [id], onDelete: SetNull)\n  assignedAt        DateTime?\n  assignedBy        String? // Admin who assigned\n\n  // Tracking\n  acceptedAt DateTime?\n  arrivedAt  DateTime?\n  startedAt  DateTime?\n\n  // Completion\n  completedAt    DateTime?\n  outcome        RescueOutcome?\n  rescueReport   String?        @db.Text\n  rescueImages   String[]\n  rescueDuration Int? // Minutes\n\n  // Verification\n  verifiedBy String?\n  verifiedAt DateTime?\n\n  // Emergency Details\n  isEmergency      Boolean @default(false)\n  emergencyDetails String?\n  hasBite          Boolean @default(false)\n  biteDetails      String?\n\n  // Metadata\n  source          String    @default(\"WEB\") // WEB, APP, PHONE, TELEGRAM\n  referenceNumber String?   @unique // Human-readable ref like \"BR-2024-001\"\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n  deletedAt       DateTime?\n\n  // Relations\n  timeline      RescueTimeline[]\n  notifications Notification[]\n\n  @@index([status])\n  @@index([priority])\n  @@index([municipality])\n  @@index([assignedTo])\n  @@index([createdAt])\n  @@index([userId])\n  @@index([speciesId])\n  @@map(\"rescue_requests\")\n}\n\nenum RescueStatus {\n  PENDING // New request, not assigned\n  ASSIGNED // Assigned to volunteer\n  ACCEPTED // Volunteer accepted\n  IN_PROGRESS // Volunteer en route or on site\n  COMPLETED // Successfully rescued\n  CANCELLED // Cancelled by reporter\n  CLOSED // Closed without rescue\n  EXPIRED // No response within time limit\n}\n\nenum RescuePriority {\n  LOW // Non-venomous, not urgent\n  MEDIUM // Standard rescue\n  HIGH // Venomous snake\n  CRITICAL // Bite victim, immediate danger\n}\n\nenum RescueOutcome {\n  RESCUED_RELOCATED // Snake rescued and relocated\n  ALREADY_GONE // Snake left before arrival\n  FALSE_ALARM // Not a snake or no danger\n  NO_SNAKE_FOUND // Could not locate\n  DECEASED // Snake was dead\n  REFUSED_HELP // Reporter changed mind\n}\n\nmodel RescueTimeline {\n  id       String        @id @default(uuid())\n  rescueId String\n  rescue   RescueRequest @relation(fields: [rescueId], references: [id], onDelete: Cascade)\n\n  event       String // \"CREATED\", \"ASSIGNED\", \"ACCEPTED\", \"COMPLETED\"\n  description String? @db.Text\n  metadata    Json? // Additional context\n\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  lat Float? // Location when event occurred\n  lng Float?\n\n  createdAt DateTime @default(now())\n\n  @@index([rescueId])\n  @@index([createdAt])\n  @@map(\"rescue_timelines\")\n}\n\n// ===================================================================\n// VOLUNTEER MANAGEMENT\n// ===================================================================\n\nmodel Volunteer {\n  id String @id @default(uuid())\n\n  // User Link\n  userId String? @unique\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  // Personal Information\n  name         String\n  contact      String\n  email        String?\n  address      String\n  municipality String\n  ward         Int?\n  dateOfBirth  DateTime?\n  gender       String?\n\n  // Emergency Contact\n  emergencyContact String?\n  emergencyPhone   String?\n\n  // Qualification & Experience\n  experience      String // \"Beginner\", \"Intermediate\", \"Expert\"\n  experienceYears Int?\n  vehicle         String // \"None\", \"Bike\", \"Car\", \"Both\"\n  vehicleDetails  String?\n  skills          String[] // [\"First Aid\", \"Snake Handling\", \"Photography\"]\n  certifications  String[]\n  languages       String[] @default([\"Nepali\", \"English\"])\n\n  // Availability\n  availableTime         String // \"Anytime\", \"Weekends\", \"Evenings\"\n  availableDays         String[] // [\"Monday\", \"Tuesday\", ...]\n  emergencyAvailability Boolean  @default(true)\n  isAvailableNow        Boolean  @default(false)\n  assignedZone          String?\n  coverageRadius        Int?     @default(5) // Kilometers\n\n  // Location (for dispatch)\n  currentLat         Float?\n  currentLng         Float?\n  lastLocationUpdate DateTime?\n\n  // Profile\n  imageUrl String?\n  bio      String? @db.Text\n\n  // Verification & Status\n  status          VolunteerStatus @default(PENDING)\n  verifiedAt      DateTime?\n  verifiedBy      String?\n  rejectedAt      DateTime?\n  rejectedBy      String?\n  rejectionReason String?\n\n  // Performance Metrics\n  totalRescues        Int    @default(0)\n  completedRescues    Int    @default(0)\n  cancelledRescues    Int    @default(0)\n  successRate         Float?\n  averageResponseTime Int? // Minutes\n  averageRescueTime   Int? // Minutes\n  rating              Float?\n  totalRatings        Int    @default(0)\n\n  // Training & Certification\n  trainingCompleted   Boolean   @default(false)\n  trainingDate        DateTime?\n  certificationExpiry DateTime?\n\n  // Equipment\n  hasEquipment Boolean  @default(false)\n  equipment    String[] // [\"Snake Hook\", \"Tongs\", \"Bag\", \"Boots\"]\n\n  // Metadata\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  // Relations\n  rescueAssignments RescueRequest[]\n  trainings         Training[]\n\n  @@index([status])\n  @@index([municipality])\n  @@index([isAvailableNow])\n  @@index([userId])\n  @@map(\"volunteers\")\n}\n\nenum VolunteerStatus {\n  PENDING // Application submitted\n  APPROVED // Basic approval\n  VERIFIED // Fully verified rescuer\n  SUSPENDED // Temporarily suspended\n  REJECTED // Application rejected\n  INACTIVE // Inactive/retired\n}\n\nmodel Training {\n  id String @id @default(uuid())\n\n  title       String\n  description String? @db.Text\n  type        String // \"BASIC\", \"ADVANCED\", \"REFRESHER\", \"FIRST_AID\"\n\n  // Schedule\n  scheduledAt DateTime\n  duration    Int // Minutes\n  location    String\n  instructor  String?\n\n  // Capacity\n  maxParticipants Int @default(20)\n  registeredCount Int @default(0)\n\n  // Status\n  status String @default(\"SCHEDULED\") // SCHEDULED, ONGOING, COMPLETED, CANCELLED\n\n  // Materials\n  materials   String[] // URLs to training materials\n  certificate String? // Certificate template\n\n  // Metadata\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  participants User[]\n  volunteers   Volunteer[]\n\n  @@index([scheduledAt])\n  @@index([status])\n  @@map(\"trainings\")\n}\n\n// ===================================================================\n// SNAKE SPECIES DATABASE\n// ===================================================================\n\nmodel SnakeSpecies {\n  id String @id @default(uuid())\n\n  // Nomenclature\n  name           String   @unique // English common name\n  scientificName String   @unique\n  nepaliName     String\n  localNames     String[] // Regional names\n  aliases        String[] // Alternative names\n\n  // Classification\n  family  String?\n  genus   String?\n  species String?\n\n  // Danger Assessment\n  venomous    Boolean      @default(false)\n  dangerLevel DangerLevel?\n  venomType   String? // \"Neurotoxic\", \"Hemotoxic\", \"Cytotoxic\"\n\n  // Physical Characteristics\n  averageLength       String? // \"60-90 cm\"\n  maxLength           String?\n  color               String?\n  pattern             String?\n  identificationGuide String?  @db.Text\n  distinctiveFeatures String[]\n\n  // Behavior & Habitat\n  behavior   String? @db.Text\n  habitat    String? @db.Text\n  activeTime String? // \"Nocturnal\", \"Diurnal\", \"Both\"\n  diet       String?\n\n  // Safety Information\n  safetyTips      String?  @db.Text\n  emergencyAdvice String?  @db.Text\n  firstAidSteps   String[]\n\n  // Distribution\n  foundInNepal  Boolean  @default(true)\n  regions       String[] // Districts/regions\n  altitudeRange String? // \"0-1000m\"\n\n  // Conservation\n  conservationStatus String? // \"Least Concern\", \"Endangered\", etc.\n  protected          Boolean @default(false)\n\n  // Media\n  imageUrl String?\n  images   String[]\n  videoUrl String?\n\n  // Statistics\n  rescueCount         Int @default(0)\n  identificationCount Int @default(0)\n\n  // Metadata\n  verified   Boolean   @default(false)\n  verifiedBy String?\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n  deletedAt  DateTime?\n\n  // Relations\n  rescueRequests    RescueRequest[]\n  aiIdentifications AIIdentification[]\n\n  @@index([venomous])\n  @@index([dangerLevel])\n  @@index([family])\n  @@map(\"snake_species\")\n}\n\nenum DangerLevel {\n  HARMLESS // No venom, no danger\n  MILDLY_VENOMOUS // Mild symptoms\n  MEDICALLY_SIGNIFICANT // Requires medical attention\n  HIGHLY_DANGEROUS // Can be fatal\n}\n\n// ===================================================================\n// AI SNAKE IDENTIFICATION\n// ===================================================================\n\nmodel AIIdentification {\n  id String @id @default(uuid())\n\n  // Input\n  imageUrl       String\n  imageThumbnail String?\n  uploadSource   String  @default(\"WEB\") // WEB, APP, API\n\n  // Results\n  speciesId  String?\n  species    SnakeSpecies? @relation(fields: [speciesId], references: [id], onDelete: SetNull)\n  confidence Float // 0.0 to 1.0\n\n  // Alternative Matches\n  alternativeMatches Json? // [{ speciesId, confidence, name }]\n\n  // AI Provider Details\n  provider     String // \"gemini\", \"openai\", \"claude\", \"local\"\n  model        String // \"gemini-1.5-pro\", \"gpt-4-vision\", etc.\n  promptUsed   String? @db.Text\n  responseTime Int? // Milliseconds\n\n  // Additional Analysis\n  venomousDetected Boolean?\n  dangerAssessment String?\n  colorDetected    String[]\n  sizeEstimate     String?\n\n  // User Context\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  // Feedback\n  userFeedback     String? // \"CORRECT\", \"INCORRECT\", \"PARTIAL\"\n  correctSpeciesId String? // If user corrects identification\n\n  // Metadata\n  createdAt DateTime @default(now())\n\n  // Relations\n  rescueRequest RescueRequest?\n\n  @@index([speciesId])\n  @@index([userId])\n  @@index([provider])\n  @@index([createdAt])\n  @@map(\"ai_identifications\")\n}\n\n// ===================================================================\n// CONTENT MANAGEMENT SYSTEM (CMS)\n// ===================================================================\n\nmodel BlogPost {\n  id String @id @default(uuid())\n\n  // Content\n  title   String\n  slug    String  @unique\n  content String  @db.Text\n  excerpt String? @db.Text\n\n  // Categorization\n  category String   @default(\"News\") // News, Education, Research, Success Story\n  tags     String[]\n\n  // Author\n  authorId String\n  author   User   @relation(fields: [authorId], references: [id], onDelete: Cascade)\n\n  // Publishing\n  status      PostStatus @default(DRAFT)\n  publishedAt DateTime?\n  scheduledAt DateTime? // For scheduled publishing\n\n  // Media\n  imageUrl String? // Featured image\n  images   String[] // Content images\n  videoUrl String?\n\n  // SEO\n  metaTitle       String?\n  metaDescription String?\n  metaKeywords    String[]\n\n  // Engagement\n  views  Int @default(0)\n  likes  Int @default(0)\n  shares Int @default(0)\n\n  // Comments (future feature)\n  commentsEnabled Boolean @default(true)\n  commentCount    Int     @default(0)\n\n  // Metadata\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  @@index([status])\n  @@index([category])\n  @@index([authorId])\n  @@index([publishedAt])\n  @@index([slug])\n  @@map(\"blog_posts\")\n}\n\nenum PostStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n  SCHEDULED\n}\n\nmodel GalleryImage {\n  id String @id @default(uuid())\n\n  // Content\n  title        String?\n  description  String? @db.Text\n  imageUrl     String\n  thumbnailUrl String?\n\n  // Categorization\n  category String? // \"Rescue\", \"Species\", \"Training\", \"Event\"\n  tags     String[]\n\n  // Context\n  rescueId  String? // Link to rescue if applicable\n  speciesId String? // Link to species if applicable\n\n  // Uploader\n  uploadedBy String?\n  uploader   User?   @relation(fields: [uploadedBy], references: [id], onDelete: SetNull)\n\n  // Visibility\n  isPublic   Boolean @default(true)\n  isFeatured Boolean @default(false)\n\n  // Engagement\n  views Int @default(0)\n  likes Int @default(0)\n\n  // Metadata\n  fileSize   Int? // Bytes\n  dimensions String? // \"1920x1080\"\n  format     String? // \"jpeg\", \"png\"\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  @@index([category])\n  @@index([uploadedBy])\n  @@index([isPublic])\n  @@index([isFeatured])\n  @@map(\"gallery_images\")\n}\n\n// ===================================================================\n// DONATIONS & PAYMENTS\n// ===================================================================\n\nmodel Donation {\n  id String @id @default(uuid())\n\n  // Donor Information\n  donorId    String?\n  donor      User?   @relation(fields: [donorId], references: [id], onDelete: SetNull)\n  donorName  String\n  donorEmail String?\n  donorPhone String?\n\n  // Amount\n  amount    Float\n  currency  String @default(\"NPR\")\n  amountUSD Float? // Converted amount for reporting\n\n  // Payment Details\n  paymentMethod   PaymentMethod\n  paymentGateway  String // \"esewa\", \"khalti\", \"stripe\", \"bank\"\n  transactionId   String?       @unique\n  gatewayResponse Json? // Full gateway response\n\n  // Status\n  status PaymentStatus @default(PENDING)\n  paidAt DateTime?\n\n  // Purpose\n  purpose   String? // \"General\", \"Emergency Fund\", \"Equipment\", \"Training\"\n  campaign  String? // Specific campaign\n  message   String? @db.Text\n  anonymous Boolean @default(false)\n\n  // Receipt\n  receiptNumber String? @unique\n  receiptUrl    String?\n  invoiceUrl    String?\n\n  // Verification\n  verifiedAt        DateTime?\n  verifiedBy        String?\n  verificationNotes String?\n\n  // Refund\n  refundedAt   DateTime?\n  refundReason String?\n  refundAmount Float?\n\n  // Metadata\n  ipAddress String?\n  userAgent String?\n  source    String  @default(\"WEB\") // WEB, APP, ADMIN\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n  @@index([paymentMethod])\n  @@index([donorId])\n  @@index([createdAt])\n  @@map(\"donations\")\n}\n\nenum PaymentMethod {\n  ESEWA\n  KHALTI\n  IME_PAY\n  FONEPAY\n  BANK_TRANSFER\n  STRIPE\n  PAYPAL\n  CASH\n}\n\nenum PaymentStatus {\n  PENDING\n  PROCESSING\n  COMPLETED\n  FAILED\n  REFUNDED\n  CANCELLED\n}\n\n// ===================================================================\n// NOTIFICATIONS & MESSAGING\n// ===================================================================\n\nmodel Notification {\n  id String @id @default(uuid())\n\n  // Recipient\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Content\n  type      NotificationType\n  title     String\n  message   String           @db.Text\n  link      String?\n  actionUrl String?\n\n  // Delivery Channels\n  sentViaApp      Boolean @default(true)\n  sentViaEmail    Boolean @default(false)\n  sentViaSMS      Boolean @default(false)\n  sentViaTelegram Boolean @default(false)\n\n  // Status\n  read   Boolean   @default(false)\n  readAt DateTime?\n\n  // Context\n  rescueId String?\n  rescue   RescueRequest? @relation(fields: [rescueId], references: [id], onDelete: Cascade)\n\n  // Metadata\n  metadata  Json?\n  priority  String    @default(\"NORMAL\") // LOW, NORMAL, HIGH, URGENT\n  expiresAt DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId, read])\n  @@index([type])\n  @@index([createdAt])\n  @@map(\"notifications\")\n}\n\nenum NotificationType {\n  RESCUE_CREATED\n  RESCUE_ASSIGNED\n  RESCUE_ACCEPTED\n  RESCUE_COMPLETED\n  RESCUE_CANCELLED\n  VOLUNTEER_APPROVED\n  VOLUNTEER_REJECTED\n  TRAINING_SCHEDULED\n  TRAINING_REMINDER\n  DONATION_RECEIVED\n  SYSTEM_ALERT\n  ANNOUNCEMENT\n}\n\n// ===================================================================\n// CONTACT & INQUIRIES\n// ===================================================================\n\nmodel ContactMessage {\n  id String @id @default(uuid())\n\n  // Sender\n  name    String\n  email   String\n  phone   String?\n  subject String\n  message String  @db.Text\n\n  // Classification\n  category String @default(\"GENERAL\") // GENERAL, RESCUE, VOLUNTEER, DONATION, TECHNICAL\n  priority String @default(\"NORMAL\")\n\n  // Status\n  status     String  @default(\"NEW\") // NEW, READ, RESPONDED, CLOSED\n  assignedTo String?\n\n  // Response\n  responded   Boolean   @default(false)\n  respondedAt DateTime?\n  response    String?   @db.Text\n\n  // Metadata\n  ipAddress String?\n  userAgent String?\n  source    String  @default(\"WEB\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n  @@index([category])\n  @@index([createdAt])\n  @@map(\"contact_messages\")\n}\n\n// ===================================================================\n// AUDIT & ACTIVITY LOGS\n// ===================================================================\n\nmodel ActivityLog {\n  id String @id @default(uuid())\n\n  // Actor\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  // Action\n  action   String // \"LOGIN\", \"LOGOUT\", \"CREATE_RESCUE\", \"UPDATE_STATUS\", etc.\n  entity   String? // \"RescueRequest\", \"Volunteer\", \"User\", etc.\n  entityId String?\n\n  // Details\n  description String?\n  metadata    Json? // Additional context\n\n  // Changes (for audit trail)\n  oldValues Json?\n  newValues Json?\n\n  // Request Context\n  ipAddress String?\n  userAgent String?\n  method    String? // GET, POST, PUT, DELETE\n  url       String?\n\n  // Result\n  success      Boolean @default(true)\n  errorMessage String?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([action])\n  @@index([entity, entityId])\n  @@index([createdAt])\n  @@map(\"activity_logs\")\n}\n\n// ===================================================================\n// SYSTEM CONFIGURATION\n// ===================================================================\n\nmodel SystemSetting {\n  id String @id @default(uuid())\n\n  key      String @unique\n  value    String @db.Text\n  type     String @default(\"STRING\") // STRING, NUMBER, BOOLEAN, JSON\n  category String @default(\"GENERAL\")\n\n  description String?\n  isPublic    Boolean @default(false)\n\n  updatedBy String?\n  updatedAt DateTime @updatedAt\n  createdAt DateTime @default(now())\n\n  @@index([category])\n  @@map(\"system_settings\")\n}\n"
}

